fn linear_search(nums: Vec<i32>, target: i32) -> i32 {
    for (index, &num) in nums.iter().enumerate() {
        if num == target {
            return index as i32; // Return the index as i32
        }
    }
    -1 // Return -1 if the target is not found
}

fn main() {
    // Example usage
    let nums = vec![1, 2, 3, 4, 5];
    let target = 3;
    let result = linear_search(nums, target);
    println!("The index of the target is: {}", result); // Output: The index of the target is: 2
}